function sync(){$('strokes').textContent=strokes;$('stars').textContent=collected;$('shoot').disabled=rolling||sunk||paused;$('shotState').textContent=paused?'休息一下':sunk?'漂亮入洞！':rolling?'小球飞驰中…':'轮到你啦';$('holes').innerHTML=levels.map((l,i)=>`<button class="${i===index?'active':results[i]?'done':''}" data-level="${i}" title="${l.name}">${results[i]&&i!==index?'✓':String(i+1).padStart(2,'0')}</button>`).join('');$('holes').querySelectorAll('button').forEach(b=>b.onclick=()=>{loadLevel(+b.dataset.level);toast('已抵达 '+levels[index].name)})}
